er;gap:0}\n.card[data-size=\"6x3\"] .nm,.card[data-size=\"6x6\"] .nm{flex:none;max-width:100%}\n.card[data-size=\"6x3\"] .lb,.card[data-size=\"6x6\"] .lb{display:inline}\n.card[data-size=\"6x3\"] .hc{padding:8px;gap:4px}\n.card[data-size=\"6x3\"] .scroll{--ch:24px;--rg:3px}\n.card[data-size=\"6x3\"] .nm{padding:0}\n.card[data-size=\"6x3\"] .hint{display:none}\n.card[data-size=\"6x3\"] .form{flex-direction:row;flex-wrap:wrap;align-content:flex-start;gap:6px 10px}\n.card[data-size=\"6x3\"] .form>.fld{flex:1 1 150px;min-width:0}\n.card[data-size=\"6x3\"] .form>p{flex:1 1 100%}\n.card[data-size=\"6x6\"] .scroll{--ch:40px;--rg:12px}\n.card[data-size=\"6x6\"] .dh i{display:block}\n.card[data-size=\"6x6\"] .tot{display:inline}\n.card[data-size=\"6x6\"] .tip{display:block}\n.card[data-size=\"6x6\"] .hc{padding:14px;gap:8px}\n.card[data-size=\"6x6\"] .ttl{font-size:17px}\n";
function initialize(s){
  const base=(s&&typeof s==='object')?s:{};
  if(Array.isArray(base.habits)) return s;
  return Object.assign({},base,{
    habits:[
      {id:'h-sleep',name:'早睡',target:5},
      {id:'h-stretch',name:'拉伸',target:5},
      {id:'h-read',name:'阅读',target:5}
    ],
    logs:(base.logs&&typeof base.logs==='object')?base.logs:{}
  });
}

function pad2(n){return n<10?'0'+n:''+n;}
function fmtDay(dt){return dt.getFullYear()+'-'+pad2(dt.getMonth()+1)+'-'+pad2(dt.getDate());}

function lastDays(today,n){
  const p=String(today).split('-').map(Number);
  const out=[];
  for(let i=n-1;i>=0;i--){
    const dt=new Date(p[0],p[1]-1,p[2]-i);
    out.push({
      key:fmtDay(dt),
      wd:'日一二三四五六'.charAt(dt.getDay()),
      md:(dt.getMonth()+1)+'/'+dt.getDate(),
      today:i===0
    });
  }
  return out;
}

function clampTarget(v){
  const n=Math.round(Number(v));
  if(!isFinite(n)) return 5;
  return Math.min(7,Math.max(1,n));
}
function normHabits(s){return Array.isArray(s&&s.habits)?s.habits:[];}
function habitLog(s,id){
  const l=s&&s.logs&&s.logs[id];
  return (l&&typeof l==='object')?l:{};
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day}=ctx;
  const habits=normHabits(state);
  const today=day();
  const days=lastDays(today,7);
  const msgOf=(e)=>(e&&e.message)?e.message:'请稍后重试';

  function toggle(hid,dk){
    ui.err='';
    update(s=>{
      const logs=Object.assign({},s.logs||{});
      const mine=Object.assign({},habitLog(s,hid));
      if(mine[dk]) delete mine[dk]; else mine[dk]=true;
      logs[hid]=mine;
      return Object.assign({},s,{logs:logs});
    }).catch(e=>{ui.err='保存失败：'+msgOf(e);redraw();});
  }

  function openEdit(h){
    ui.err='';
    ui.edit={
      id:h?h.id:null,
      name:h?h.name:'',
      target:h?clampTarget(h.target):5,
      confirm:false,
      err:''
    };
    redraw();
  }
  function closeEdit(){ui.edit=null;redraw();}

  function saveEdit(){
    const e=ui.edit;
    if(!e) return;
    const name=String(e.name||'').trim().slice(0,20);
    if(!name){e.err='请先填写习惯名称';redraw();return;}
    const target=clampTarget(e.target);
    const id=e.id||uid();
    commit(s=>{
      const list=normHabits(s).slice();
      const i=list.findIndex(h=>h.id===id);
      if(i>=0) list[i]=Object.assign({},list[i],{name:name,target:target});
      else list.push({id:id,name:name,target:target});
      return Object.assign({},s,{habits:list});
    },{edit:null,err:''}).catch(er=>{e.err='保存失败：'+msgOf(er);redraw();});
  }

  function removeHabit(){
    const e=ui.edit;
    if(!e||!e.id) return;
    const id=e.id;
    commit(s=>{
      const logs=Object.assign({},s.logs||{});
      delete logs[id];
      return Object.assign({},s,{habits:normHabits(s).filter(h=>h.id!==id),logs:logs});
    },{edit:null,err:''}).catch(er=>{e.err='删除失败：'+msgOf(er);e.confirm=false;redraw();});
  }

  const btn=(label,cls,onclick)=>el('button',{type:'button',class:'btn '+cls,onclick:onclick},label);


  function buildRow(h){
    const log=habitLog(state,h.id);
    const target=clampTarget(h.target);
    const n=days.filter(d=>log[d.key]).length;
    const total=Object.keys(log).length;
    const met=n>=target;

    const nm=el('button',{type:'button',class:'nm',title:'编辑：'+h.name,'aria-label':'编辑习惯 '+h.name,onclick:()=>openEdit(h)},
      el('span',{class:'nmt'},h.name),
      el('span',{class:'pen','aria-hidden':'true'},'✎'));

    const ct=el('span',{class:'ct'},
      el('span',{class:'lb'},'近7天 '),
      el('span',{class:'cn'},n+'/'+target));
    if(met) ct.append(el('span',{class:'ok'},'✓达标'));
    ct.append(el('span',{class:'tot'},' · 累计 '+total));

    const cells=days.map(d=>{
      const done=!!log[d.key];
      const cls='cell'+(done?' done':'')+(d.today?' tdy':'')+((!done&&!d.today)?' miss':'');
      const act=done?'已完成，点按取消':(d.today?'未完成，点按打卡':'未打卡，点按补记');
      return el('button',{type:'button',class:cls,'aria-pressed':done?'true':'false',
        'aria-label':h.name+' '+d.md+' '+act,title:d.md+' '+act,
        onclick:()=>toggle(h.id,d.key)},done?'✓':'');
    });
    return el('div',{class:'hr'},el('div',{class:'hn'},nm,ct),...cells);
  }

  function buildList(){
    if(!habits.length){
      return el('div',{class:'empty'},
        el('p',{},'还没有习惯，先添加一个吧。'),
        btn('添加习惯','pri',()=>openEdit(null)));
    }
    const head=el('div',{class:'dayhead'},
      el('span',{class:'sp'}),
      ...days.map(d=>el('span',{class:'dh'+(d.today?' today':'')},
        el('b',{},d.wd),el('i',{},d.md))));
    const rows=el('div',{class:'scroll'},...habits.map(buildRow));
    return el('div',{class:'list'},head,rows,
      el('p',{class:'tip'},'点格子打卡；漏打的日子直接点击补记，再点一次取消。漏打不会清除之前的记录。'));
  }

  function buildEdit(){
    const e=ui.edit;
    const isNew=!e.id;
    const total=isNew?0:Object.keys(habitLog(state,e.id)).length;

    const input=el('input',{type:'text',class:'inp',value:e.name,maxlength:'20',
      placeholder:'习惯名称，例如 早睡','aria-label':'习惯名称',
      oninput:ev=>{e.name=ev.target.value;},
      onkeydown:ev=>{if(ev.key==='Enter'){ev.preventDefault();saveEdit();}}});

    const seg=el('div',{class:'seg',role:'group','aria-label':'每周目标次数'},
      ...[1,2,3,4,5,6,7].map(k=>el('button',{type:'button',
        class:'sg'+(e.target===k?' on':''),
        'aria-pressed':e.target===k?'true':'false',
        'aria-label':'每周 '+k+' 次',
        onclick:()=>{e.target=k;redraw();}},String(k))));

    const form=el('div',{class:'form'},
      el('label',{class:'fld'},el('span',{},'名称'),input),
      el('div',{class:'fld'},el('span',{},'每周目标（当前 '+e.target+' 次）'),seg));
    if(!isNew) form.append(el('p',{class:'hint'},'已记录 '+total+' 天。改名或改目标不会影响已有记录。'));
    if(e.confirm) form.append(el('p',{class:'warn',role:'alert'},'⚠ 删除「'+e.name+'」会同时清除它的 '+total+' 天打卡记录，且无法恢复。'));
    if(e.err) form.append(el('p',{class:'warn',role:'alert'},'⚠ '+e.err));

    let foot;
    if(e.confirm){
      foot=el('div',{class:'foot'},
        btn('确认删除','pri',removeHabit),
        btn('取消','',()=>{e.confirm=false;redraw();}));
    }else{
      foot=el('div',{class:'foot'},
        btn('保存','pri',saveEdit),
        btn('取消','',closeEdit));
      if(!isNew) foot.append(btn('删除','',()=>{e.confirm=true;redraw();}));
    }
    return el('div',{class:'editor'},form,foot);
  }

  const editing=!!ui.edit;
  const top=el('div',{class:'top'},
    el('h2',{class:'ttl'},editing?(ui.edit.id?'编辑习惯':'新增习惯'):'习惯打卡'));
  if(!editing && habits.length){
    const doneToday=habits.filter(h=>habitLog(state,h.id)[today]).length;
    top.append(el('span',{class:'stat'},'今日 '+doneToday+'/'+habits.length));
  }
  if(!editing){
    top.append(el('button',{type:'button',class:'add','aria-label':'添加习惯',title:'添加习惯',onclick:()=>openEdit(null)},'+'));
  }

  const wrap=el('div',{class:'hc'},top);
  if(ui.err && !editing) wrap.append(el('p',{class:'err',role:'alert'},'⚠ '+ui.err));
  wrap.append(editing?buildEdit():buildList());
  root.append(wrap);
}

